// Scientific arrays generated by scan_hf_field_gradient.py.
use anyhow::Result;
use hdf5::File;
use rustplotlib::*;
const BLUE:&str="#245774";const RED:&str="#8b3940";const GREEN:&str="#4c7566";
fn rd(h:&File,k:&str)->Result<Vec<f64>>{Ok(h.dataset(&format!("plot/{k}"))?.read_raw::<f64>()?)}
fn line(f:&mut Figure,p:usize,x:&[f64],y:&[f64],col:&str,width:f64){
 let a=f.panels[p].axes.as_ref().unwrap();let points=x.iter().zip(y).filter(|(x,y)|x.is_finite()&&y.is_finite()&&**x>=a.xlim[0]&&**x<=a.xlim[1]&&**y>=a.ylim[0]&&**y<=a.ylim[1]).map(|(&x,&y)|[x,y]).collect();let mut l=Line::new(points,col);l.width_pt=width;f.panels[p].push(Layer::Line(l));
}
fn legend(f:&mut Figure,p:usize,entries:Vec<LegendEntry>){let mut l=Legend::new(entries);l.columns=1;f.panels[p].legend=Some(l);}
fn save(f:&Figure,name:&str)->Result<()>{for ext in ["png","pdf"]{f.save(format!("figures/{name}.{ext}"))?;}Ok(())}
fn main()->Result<()>{
 let h=File::open("output/fluid/hf_field_gradient.h5")?;let z=rd(&h,"height_m")?;
 let mut f=Figure::new(IntendedUse::ArticleWide);let ps=f.grid(1,2)?;f.width_mm=235.;f.height_mm=145.;
 for i in 0..2{f.panels[ps[i]].rect=Rect::new(25.+116.*i as f64,9.,81.,108.);let mut a=Axes::new(if i==0{[1e-6,1.]}else{[1e-9,1e-4]},[-6.,2.],r"Field-gradient magnitude (V/m$^2$)","Height relative to resonance (m)");a.set_xscale(AxisScale::Log10)?;f.panels[ps[i]].axes=Some(a);let lim=f.panels[ps[i]].axes.as_ref().unwrap().xlim;let zb=h.attr("bragg_height_relative_m")?.read_scalar::<f64>()?;line(&mut f,ps[i],&lim,&[zb,zb],"#a4acb2",0.65);}
 line(&mut f,ps[0],&rd(&h,"cold_gradient")?,&z,BLUE,1.2);line(&mut f,ps[0],&rd(&h,"warm_gradient")?,&z,RED,1.2);
 legend(&mut f,ps[0],vec![LegendEntry::line("Cold HF field",BLUE),LegendEntry::line("Warm total field",RED)]);
 line(&mut f,ps[1],&rd(&h,"source_gradient")?,&z,BLUE,1.2);line(&mut f,ps[1],&rd(&h,"effective_gradient")?,&z,GREEN,1.2);
 legend(&mut f,ps[1],vec![LegendEntry::line(r"Imposed $E_z$",BLUE),LegendEntry::line("Effective drive",GREEN)]);
 save(&f,"hf_vertical_field_gradient")?;
 let mut f=Figure::new(IntendedUse::ArticleWide);let ps=f.grid(1,2)?;f.width_mm=235.;f.height_mm=145.;
 for i in 0..2{f.panels[ps[i]].rect=Rect::new(25.+116.*i as f64,9.,81.,108.);let mut a=Axes::new([0.02,20.],if i==0{[0.5,30.]}else{[18.,35.]},r"Smoothing width $\sigma$ (m)",if i==0{r"Peak imposed $E_z$ gradient ($\mu$V/m$^2$)"}else{"Predicted plasma-line SNR (dB)"});a.set_xscale(AxisScale::Log10)?;if i==0{a.set_yscale(AxisScale::Log10)?;}f.panels[ps[i]].axes=Some(a);}
 let sig=rd(&h,"sigma_m")?;
 for (i,key,attr) in [(0,"scan_gradient_microV_m2","baseline_gradient_microV_m2"),(1,"scan_snr_db","baseline_snr_db")]{let refv=h.group("plot")?.attr(attr)?.read_scalar::<f64>()?;line(&mut f,ps[i],&[0.02,20.],&[refv,refv],GREEN,0.7);line(&mut f,ps[i],&sig,&rd(&h,key)?,BLUE,1.2);legend(&mut f,ps[i],vec![LegendEntry::line("Smoothed",BLUE),LegendEntry::line("Original",GREEN)]);}
 save(&f,"hf_field_gradient_scan")?;
 Ok(())
}
